package finance.data.serializer;

import finance.bank.*;
import net.minecraft.nbt.*;
import java.math.BigInteger;
import java.util.*;

/** Bounded banking persistence. A bank is accepted only when its restored ledger and customer sub-ledger agree. */
public final class BankingDataSerializer {
    private BankingDataSerializer() { }
    public static void save(CompoundTag root){CompoundTag state=new CompoundTag();state.putLong("LastDepositDay",BankingManager.lastDepositDay());state.putLong("LastSnapshotDay",BankingManager.lastSnapshotDay());ListTag banks=new ListTag();for(CommercialBank b:BankingManager.banks().values()){CompoundTag t=new CompoundTag();t.putUUID("Id",b.id());t.putString("Code",b.code());t.putString("Name",b.name());t.putString("Status",b.status().name());t.putLong("Capital",b.paidInCapital());t.putInt("DemandSpread",b.policy().demandSpreadBps());t.putInt("TimeSpread",b.policy().timeSpreadBps());t.putInt("LoanSpread",b.policy().loanSpreadBps());t.putInt("TargetReserve",b.policy().targetReserveBps());t.putInt("BorrowerLimit",b.policy().singleBorrowerLimitBps());ListTag entries=new ListTag();for(BankLedgerEntry e:b.ledger().entries()){CompoundTag x=new CompoundTag();x.putUUID("Entry",e.entryId());x.putUUID("Reference",e.referenceId());x.putLong("Day",e.mcDay());x.putString("Debit",e.debit().name());x.putString("Credit",e.credit().name());x.putLong("Amount",e.amount());x.putString("Reason",e.reason().name());entries.add(x);}t.put("Entries",entries);ListTag snapshots=new ListTag();for(BankBalanceSheetSnapshot s:b.snapshots()){CompoundTag x=new CompoundTag();x.putLong("Day",s.mcDay());x.putLong("Profit",s.dailyProfit());x.putLong("Npl",s.nonPerformingLoans());x.putInt("Lcr",s.liquidityCoverageBps());x.putInt("Car",s.capitalAdequacyBps());writeSheet(x,s.sheet());snapshots.add(x);}t.put("Snapshots",snapshots);banks.add(t);}state.put("Banks",banks);
        ListTag accounts=new ListTag();for(BankCustomerAccount a:BankingManager.accounts().values()){CompoundTag t=new CompoundTag();t.putUUID("Id",a.id());t.putUUID("Bank",a.bankId());t.putUUID("Owner",a.ownerId());t.putString("OwnerType",a.ownerType().name());t.putString("Type",a.type().name());t.putLong("Balance",a.balance());t.putLong("Frozen",a.frozen());t.putLong("Opened",a.openedDay());t.putString("Status",a.status().name());accounts.add(t);}state.put("Accounts",accounts);
        ListTag terms=new ListTag();for(TimeDeposit d:BankingManager.timeDeposits().values()){CompoundTag t=new CompoundTag();t.putUUID("Id",d.id());t.putUUID("Bank",d.bankId());t.putUUID("Owner",d.ownerId());t.putUUID("Account",d.accountId());t.putLong("Principal",d.principal());t.putInt("Rate",d.lockedRateBps());t.putLong("Start",d.startDay());t.putLong("Maturity",d.maturityDay());t.putLong("Interest",d.accruedInterest());t.putLong("LastAccrual",d.lastAccrualDay());t.putString("Status",d.status().name());terms.add(t);}state.put("TimeDeposits",terms);
        ListTag interbank=new ListTag();for(InterbankLoan l:InterbankMarketService.loans().values()){CompoundTag t=new CompoundTag();t.putUUID("Id",l.id());t.putUUID("Lender",l.lenderBankId());t.putUUID("Borrower",l.borrowerBankId());t.putLong("Principal",l.principal());t.putInt("Rate",l.rateBasisPoints());t.putLong("Issue",l.issueDay());t.putLong("Maturity",l.maturityDay());t.putString("Status",l.status().name());interbank.add(t);}state.put("Interbank",interbank);state.putLong("InterbankDay",InterbankMarketService.lastProcessedDay());
        ListTag cb=new ListTag();for(CentralBankLiquidityLoan l:CentralBankLiquidityService.loans().values()){CompoundTag t=new CompoundTag();t.putUUID("Id",l.id());t.putUUID("Bank",l.bankId());t.putLong("Principal",l.principal());t.putInt("Rate",l.rateBasisPoints());t.putLong("Issue",l.issueDay());t.putLong("Maturity",l.maturityDay());t.putString("Status",l.status().name());cb.add(t);}state.put("CentralBankLoans",cb);state.putLong("CentralIssued",CentralBankLiquidityService.cumulativeIssued());state.putLong("CentralDay",CentralBankLiquidityService.lastProcessedDay());state.putLong("ReserveInterestIssued",CentralBankLiquidityService.cumulativeReserveInterest());state.putLong("ReserveInterestDay",CentralBankLiquidityService.lastReserveInterestDay());state.putLong("InsuranceFund",DepositInsuranceService.fund());state.putLong("InsuranceDay",DepositInsuranceService.lastPremiumDay());ListTag resolved=new ListTag();for(UUID id:DepositInsuranceService.resolvedBanks()){CompoundTag t=new CompoundTag();t.putUUID("Id",id);resolved.add(t);}state.put("Resolved",resolved);root.put("Banking",state);}
    public static void load(CompoundTag root){BankingManager.clearDirect();InterbankMarketService.clearDirect();CentralBankLiquidityService.clearDirect();DepositInsuranceService.clearDirect();if(!root.contains("Banking",Tag.TAG_COMPOUND)){BankingManager.ensureDefaultBanks();return;}CompoundTag state=root.getCompound("Banking");Set<UUID>bankIds=new HashSet<>();for(Tag raw:state.getList("Banks",Tag.TAG_COMPOUND)){if(bankIds.size()>=BankingManager.MAX_BANKS)break;CompoundTag t=(CompoundTag)raw;UUID id=NbtDataSupport.readUuidOrNull(t,"Id");BankStatus status=NbtDataSupport.safeEnum(BankStatus.class,t.getString("Status"),null);if(id==null||!bankIds.add(id)||status==null)continue;try{BankPolicy policy=new BankPolicy(t.getInt("DemandSpread"),t.getInt("TimeSpread"),t.getInt("LoanSpread"),t.getInt("TargetReserve"),t.getInt("BorrowerLimit"));CommercialBank b=new CommercialBank(id,t.getString("Code"),t.getString("Name"),status,t.getLong("Capital"),policy);List<BankLedgerEntry>entries=new ArrayList<>();for(Tag er:t.getList("Entries",Tag.TAG_COMPOUND)){if(entries.size()>=BankLedger.MAX_ENTRIES){entries.clear();break;}CompoundTag e=(CompoundTag)er;UUID eid=NbtDataSupport.readUuidOrNull(e,"Entry"),ref=NbtDataSupport.readUuidOrNull(e,"Reference");var debit=NbtDataSupport.safeEnum(BankLedgerAccount.class,e.getString("Debit"),null);var credit=NbtDataSupport.safeEnum(BankLedgerAccount.class,e.getString("Credit"),null);var reason=NbtDataSupport.safeEnum(BankLedgerReason.class,e.getString("Reason"),null);try{entries.add(new BankLedgerEntry(eid,id,e.getLong("Day"),debit,credit,e.getLong("Amount"),reason,ref));}catch(IllegalArgumentException ignored){entries.clear();break;}}if(entries.isEmpty()||!b.ledger().restore(entries))continue;for(Tag sr:t.getList("Snapshots",Tag.TAG_COMPOUND)){CompoundTag s=(CompoundTag)sr;try{BankBalanceSheet sheet=readSheet(s);if(sheet.balanced())b.addSnapshot(new BankBalanceSheetSnapshot(id,s.getLong("Day"),sheet,s.getLong("Profit"),s.getLong("Npl"),s.getInt("Lcr"),s.getInt("Car")));}catch(IllegalArgumentException ignored){}}BankingManager.putBankDirect(b);}catch(IllegalArgumentException ignored){}}
        Set<UUID>accountIds=new HashSet<>();for(Tag raw:state.getList("Accounts",Tag.TAG_COMPOUND)){if(accountIds.size()>=BankingManager.MAX_ACCOUNTS)break;CompoundTag t=(CompoundTag)raw;UUID id=NbtDataSupport.readUuidOrNull(t,"Id"),bank=NbtDataSupport.readUuidOrNull(t,"Bank"),owner=NbtDataSupport.readUuidOrNull(t,"Owner");var ownerType=NbtDataSupport.safeEnum(CustomerType.class,t.getString("OwnerType"),null);var type=NbtDataSupport.safeEnum(BankAccountType.class,t.getString("Type"),null);var status=NbtDataSupport.safeEnum(BankAccountStatus.class,t.getString("Status"),null);if(id==null||!accountIds.add(id)||BankingManager.bank(bank)==null)continue;try{BankingManager.putAccountDirect(new BankCustomerAccount(id,bank,owner,ownerType,type,t.getLong("Balance"),t.getLong("Frozen"),t.getLong("Opened"),status));}catch(IllegalArgumentException ignored){}}
        Set<UUID>termIds=new HashSet<>();for(Tag raw:state.getList("TimeDeposits",Tag.TAG_COMPOUND)){if(termIds.size()>=BankingManager.MAX_TIME_DEPOSITS)break;CompoundTag t=(CompoundTag)raw;UUID id=NbtDataSupport.readUuidOrNull(t,"Id"),bank=NbtDataSupport.readUuidOrNull(t,"Bank"),owner=NbtDataSupport.readUuidOrNull(t,"Owner"),account=NbtDataSupport.readUuidOrNull(t,"Account");var status=NbtDataSupport.safeEnum(TimeDepositStatus.class,t.getString("Status"),null);BankCustomerAccount a=BankingManager.account(account);if(id==null||!termIds.add(id)||a==null||a.type()!=BankAccountType.TIME_DEPOSIT||!a.bankId().equals(bank)||!a.ownerId().equals(owner))continue;try{TimeDeposit d=new TimeDeposit(id,bank,owner,account,t.getLong("Principal"),t.getInt("Rate"),t.getLong("Start"),t.getLong("Maturity"),t.getLong("Interest"),t.getLong("LastAccrual"),status);if((status==TimeDepositStatus.ACTIVE||status==TimeDepositStatus.MATURED)&&BigInteger.valueOf(d.principal()).add(BigInteger.valueOf(d.accruedInterest())).equals(BigInteger.valueOf(a.balance())))BankingManager.putTimeDepositDirect(d);else if(status==TimeDepositStatus.REDEEMED&&a.status()==BankAccountStatus.CLOSED)BankingManager.putTimeDepositDirect(d);}catch(IllegalArgumentException ignored){}}
        validateCustomerLedgers();loadInterbank(state);loadCentral(state);List<UUID>resolved=new ArrayList<>();for(Tag raw:state.getList("Resolved",Tag.TAG_COMPOUND)){UUID id=NbtDataSupport.readUuidOrNull((CompoundTag)raw,"Id");if(id!=null)resolved.add(id);}DepositInsuranceService.restore(state.getLong("InsuranceFund"),state.getLong("InsuranceDay"),resolved);BankingManager.restoreDays(state.getLong("LastDepositDay"),state.getLong("LastSnapshotDay"));if(BankingManager.banks().isEmpty())BankingManager.ensureDefaultBanks();}
    private static void validateCustomerLedgers(){for(CommercialBank b:List.copyOf(BankingManager.banks().values())){BigInteger demand=BigInteger.ZERO,time=BigInteger.ZERO;for(BankCustomerAccount a:BankingManager.accounts().values())if(a.bankId().equals(b.id())&&a.status()!=BankAccountStatus.CLOSED){if(a.type()==BankAccountType.DEMAND_DEPOSIT)demand=demand.add(BigInteger.valueOf(a.balance()));else time=time.add(BigInteger.valueOf(a.balance()));}if(!demand.equals(BigInteger.valueOf(b.ledger().balance(BankLedgerAccount.LIABILITY_DEMAND_DEPOSIT)))||!time.equals(BigInteger.valueOf(b.ledger().balance(BankLedgerAccount.LIABILITY_TIME_DEPOSIT))))BankingManager.removeBankDirect(b.id());}}
    private static void loadInterbank(CompoundTag state){Set<UUID>ids=new HashSet<>();for(Tag raw:state.getList("Interbank",Tag.TAG_COMPOUND)){CompoundTag t=(CompoundTag)raw;UUID id=NbtDataSupport.readUuidOrNull(t,"Id"),l=NbtDataSupport.readUuidOrNull(t,"Lender"),b=NbtDataSupport.readUuidOrNull(t,"Borrower");var status=NbtDataSupport.safeEnum(InterbankLoanStatus.class,t.getString("Status"),null);if(id==null||!ids.add(id)||BankingManager.bank(l)==null||BankingManager.bank(b)==null)continue;try{InterbankMarketService.putDirect(new InterbankLoan(id,l,b,t.getLong("Principal"),t.getInt("Rate"),t.getLong("Issue"),t.getLong("Maturity"),status));}catch(IllegalArgumentException ignored){}}InterbankMarketService.restoreDay(state.getLong("InterbankDay"));}
    private static void loadCentral(CompoundTag state){Set<UUID>ids=new HashSet<>();for(Tag raw:state.getList("CentralBankLoans",Tag.TAG_COMPOUND)){CompoundTag t=(CompoundTag)raw;UUID id=NbtDataSupport.readUuidOrNull(t,"Id"),bank=NbtDataSupport.readUuidOrNull(t,"Bank");var status=NbtDataSupport.safeEnum(CentralBankLoanStatus.class,t.getString("Status"),null);if(id==null||!ids.add(id)||BankingManager.bank(bank)==null)continue;try{CentralBankLiquidityService.putDirect(new CentralBankLiquidityLoan(id,bank,t.getLong("Principal"),t.getInt("Rate"),t.getLong("Issue"),t.getLong("Maturity"),status));}catch(IllegalArgumentException ignored){}}CentralBankLiquidityService.restore(state.getLong("CentralIssued"),state.getLong("CentralDay"),state.getLong("ReserveInterestIssued"),state.getLong("ReserveInterestDay"));}
    private static void writeSheet(CompoundTag t,BankBalanceSheet s){t.putLong("Assets",s.totalAssets());t.putLong("Reserves",s.reserves());t.putLong("CompanyLoans",s.companyLoans());t.putLong("InterbankAssets",s.interbankAssets());t.putLong("BondAssets",s.bondAssets());t.putLong("Demand",s.demandDeposits());t.putLong("Time",s.timeDeposits());t.putLong("InterbankLiabilities",s.interbankLiabilities());t.putLong("Central",s.centralBankBorrowing());t.putLong("Equity",s.equity());t.putLong("LossReserve",s.loanLossReserve());t.putBoolean("Balanced",s.balanced());}
    private static BankBalanceSheet readSheet(CompoundTag t){return new BankBalanceSheet(t.getLong("Assets"),t.getLong("Reserves"),t.getLong("CompanyLoans"),t.getLong("InterbankAssets"),t.getLong("BondAssets"),t.getLong("Demand"),t.getLong("Time"),t.getLong("InterbankLiabilities"),t.getLong("Central"),t.getLong("Equity"),t.getLong("LossReserve"),t.getBoolean("Balanced"));}
}
